<?php
defined('BASEPATH') OR exit('No direct script access allowed');

class Chat_model extends CI_Model
{
    public function ensure_schema()
    {
        $this->db->query("CREATE TABLE IF NOT EXISTS chat_presence (user_type ENUM('citizen','admin') NOT NULL, user_id INT UNSIGNED NOT NULL, last_seen DATETIME NOT NULL, PRIMARY KEY(user_type,user_id), KEY last_seen(last_seen)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->query("CREATE TABLE IF NOT EXISTS chat_conversations (id INT UNSIGNED NOT NULL AUTO_INCREMENT, citizen_id INT UNSIGNED NOT NULL, assigned_admin_id INT UNSIGNED NULL, last_message_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY citizen_id(citizen_id), KEY assigned_admin_id(assigned_admin_id), KEY last_message_at(last_message_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->query("CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, conversation_id INT UNSIGNED NOT NULL, sender_type ENUM('citizen','admin') NOT NULL, sender_id INT UNSIGNED NOT NULL, message TEXT NOT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY conversation_messages(conversation_id,id), KEY unread_lookup(conversation_id,sender_type,is_read)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }
    public function touch($type,$id){$this->db->query("INSERT INTO chat_presence(user_type,user_id,last_seen) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE last_seen=NOW()",array($type,(int)$id));}
    public function conversation_for_citizen($citizen_id,$admin_id=NULL){$row=$this->db->get_where('chat_conversations',array('citizen_id'=>(int)$citizen_id))->row_array();if(!$row){$this->db->insert('chat_conversations',array('citizen_id'=>(int)$citizen_id,'assigned_admin_id'=>$admin_id?:NULL));$row=$this->db->get_where('chat_conversations',array('id'=>$this->db->insert_id()))->row_array();}elseif($admin_id&&(int)$row['assigned_admin_id']!==(int)$admin_id){$this->db->where('id',$row['id'])->update('chat_conversations',array('assigned_admin_id'=>(int)$admin_id));$row['assigned_admin_id']=(int)$admin_id;}return $row;}
    // Tampilan awal memakai 200 pesan terbaru; polling mengambil pesan setelah id terakhir.
    public function messages($conversation_id,$after=0){$after=(int)$after;$rows=$this->db->where('conversation_id',(int)$conversation_id)->where('id >',$after)->order_by('id',$after?'ASC':'DESC')->limit(200)->get('chat_messages')->result_array();return $after?$rows:array_reverse($rows);}
    public function read_up_to($conversation_id){$row=$this->db->select_max('id')->where('conversation_id',(int)$conversation_id)->where('sender_type','admin')->where('is_read',1)->get('chat_messages')->row_array();return (int)($row['id']??0);}
    public function send($conversation_id,$type,$sender_id,$message){$this->db->insert('chat_messages',array('conversation_id'=>(int)$conversation_id,'sender_type'=>$type,'sender_id'=>(int)$sender_id,'message'=>$message));$id=(int)$this->db->insert_id();$update=array('last_message_at'=>date('Y-m-d H:i:s'));if($type==='admin')$update['assigned_admin_id']=(int)$sender_id;$this->db->where('id',(int)$conversation_id)->update('chat_conversations',$update);return $id;}
    public function mark_read($conversation_id,$reader_type){$sender=$reader_type==='admin'?'citizen':'admin';$this->db->where('conversation_id',(int)$conversation_id)->where('sender_type',$sender)->where('is_read',0)->update('chat_messages',array('is_read'=>1));}
    public function online_admins(){return $this->db->select("admins.id,admins.username,admins.role,chat_presence.last_seen,(chat_presence.last_seen >= DATE_SUB(NOW(), INTERVAL 2 MINUTE)) AS is_online",FALSE)->join('chat_presence',"chat_presence.user_type='admin' AND chat_presence.user_id=admins.id",'left')->order_by('is_online','DESC')->order_by('admins.username','ASC')->get('admins')->result_array();}
    public function admin_conversations(){return $this->db->select("chat_conversations.*,citizens.display_name,citizens.username,citizens.gender,chat_presence.last_seen,(chat_presence.last_seen >= DATE_SUB(NOW(), INTERVAL 2 MINUTE)) AS is_online,(SELECT COUNT(*) FROM chat_messages m WHERE m.conversation_id=chat_conversations.id AND m.sender_type='citizen' AND m.is_read=0) AS unread,(SELECT message FROM chat_messages lm WHERE lm.conversation_id=chat_conversations.id ORDER BY lm.id DESC LIMIT 1) AS last_message,(SELECT created_at FROM chat_messages lt WHERE lt.conversation_id=chat_conversations.id ORDER BY lt.id DESC LIMIT 1) AS last_message_time",FALSE)->join('citizens','citizens.id=chat_conversations.citizen_id')->join('chat_presence',"chat_presence.user_type='citizen' AND chat_presence.user_id=citizens.id",'left')->order_by('chat_conversations.last_message_at','DESC')->order_by('citizens.display_name','ASC')->get('chat_conversations')->result_array();}
}
